      },
    };
    const prevRepairState: EmotionalState = {
      ...createInitialState('trigger-test-2'),
      charge: -0.2,
      threat: 0.45,
      turnId: 3,
    };

    const result = checkDeepTriggers(repairState, prevRepairState, 'I appreciate you looking into this', null);
    if (result.triggered) {
      findings.push({
        id: 'trigger-repair-block',
        category: 'trigger_gates',
        severity: 'warning',
        title: 'Repair intent did not block deep trigger',
        description: `Deep trigger fired despite repair keywords. Reasons: ${result.reasons.join(', ')}`,
        expected: 'triggered=false (repair intent block)',
        actual: `triggered=true, reasons=[${result.reasons.join(', ')}]`,
        recommendation: 'Review repair intent detection in checkDeepTriggers().',
        codeLocation: 'server/nervous-system/dynamics/runtime.ts:checkDeepTriggers()',
      });
    } else {
      findings.push({
        id: 'trigger-repair-block',
        category: 'trigger_gates',
        severity: 'pass',
        title: 'Repair intent correctly blocks deep trigger',
        description: 'Deep trigger correctly suppressed when repair keywords detected.',
        expected: 'triggered=false',
        actual: `triggered=false, reasons=[${result.reasons.join(', ')}]`,
        recommendation: 'No action needed.',
      });
    }
