  // Test 3: Rate limiting should work
  {
    const state: EmotionalState = {
      ...createInitialState('trigger-test-3'),
      charge: -0.5,
      threat: 0.8,
      acceleration: 0.9,
      turnId: 10,
      regime: 'rupture',
      history: {
        lastK: [
          { turnId: 8, mass: 0.7, distance: 0.7, charge: -0.4, threat: 0.7, regime: 'escalation', confidence: 0.6 },
          { turnId: 9, mass: 0.8, distance: 0.8, charge: -0.5, threat: 0.75, regime: 'rupture', confidence: 0.5 },
        ],
      },
    };
    const prevState: EmotionalState = {
      ...createInitialState('trigger-test-3'),
      charge: -0.5,
      threat: 0.75,
      turnId: 9,
    };

    // Last deep was 10 seconds ago (should be rate limited with 45s cooldown)
    const lastDeepTime = Date.now() - 10000;
    const result = checkDeepTriggers(state, prevState, 'This is terrible', lastDeepTime);
    if (result.triggered) {
      findings.push({
        id: 'trigger-rate-limit',
        category: 'trigger_gates',
        severity: 'critical',
        title: 'Rate limiting not working',
        description: `Deep trigger fired despite rate limiting (last deep 10s ago, cooldown 45s).`,
        expected: 'triggered=false (rate limited)',
        actual: `triggered=true, reasons=[${result.reasons.join(', ')}]`,
        recommendation: 'Review rate limiting logic in checkDeepTriggers().',
        codeLocation: 'server/nervous-system/dynamics/runtime.ts:checkDeepTriggers()',
      });
    } else {
      findings.push({
        id: 'trigger-rate-limit',
        category: 'trigger_gates',
