    const result = checkDeepTriggers(infoState, prevInfoState, 'What is your refund policy?', null);
    const fixationTriggered = result.reasons.some(r => r.includes('fixation') || r.includes('orbit'));
    if (fixationTriggered) {
      findings.push({
        id: 'trigger-info-suppress',
        category: 'trigger_gates',
        severity: 'warning',
        title: 'Informational intent did not suppress fixation/orbit triggers',
