      findings.push({
        id: 'trigger-info-suppress',
        category: 'trigger_gates',
        severity: 'pass',
        title: 'Informational intent correctly suppresses fixation triggers',
        description: 'Fixation/orbit triggers correctly suppressed for FAQ question.',
        expected: 'No fixation/orbit triggers',
        actual: `triggered=${result.triggered}, reasons=[${result.reasons.join(', ')}]`,
