    }
  }

  // Test 5: Signal detection accuracy
  {
    const signals1 = detectSignals('I want to sign up for the enterprise plan');
    if (!signals1.commitmentLanguage) {
      findings.push({
        id: 'signal-commitment',
        category: 'positive_intelligence',
        severity: 'warning',
        title: 'Commitment language not detected',
        description: '"I want to sign up for the enterprise plan" should detect commitment language.',
        expected: 'commitmentLanguage=true',
        actual: `commitmentLanguage=${signals1.commitmentLanguage}`,
        recommendation: 'Review commitment language patterns in detectSignals().',
        codeLocation: 'server/nervous-system/dynamics/state-transition-history.ts:detectSignals()',
      });
