tool_use_result.originalFile:
/**
 * Behavioral Correctness Audit
 * 
 * Claude-powered deep audit of the InteractionState runtime engine.
 * Systematically validates:
 * 1. Emotional primitive ranges & coherence
 * 2. Trigger gate correctness (over/under-triggering)
 * 3. Guidance generation quality & guardrail enforcement
 * 4. State transition coherence (benefit states, regimes)
 * 5. Positive intelligence accuracy (trust, rapport, commitment)
 * 
 * Uses synthetic conversation scenarios to exercise every code path,
 * then asks Claude to evaluate whether the engine's outputs are
 * behaviorally correct for each scenario.
 */

import { governedClaude } from './governed-anthropic';
import { extractJSON } from '../nervous-system/utils/json-parser';
import {
  processMessage,
  createInitialState,
  checkDeepTriggers,
  updateState,
  DEFAULT_TRIGGERS,
  type EmotionalState,
  type Regime,
  type BenefitState,
} from '../nervous-system/dynamics/runtime';
import {
  applyGuardrails,
  GUIDANCE_GUARDRAILS,
  ANTI_CREEPY_RULES,
} from '../nervous-system/dynamics/lexicon';
import { detectSignals } from '../nervous-system/dynamics/state-transition-history';
import { generalLog } from '../_core/logger';
import { MODELS } from "../_core/models";

// ============================================================================
// TYPES
// ============================================================================

export type AuditSeverity = 'pass' | 'info' | 'warning' | 'critical';

export interface AuditFinding {
  id: string;
  category: AuditCategory;
  severity: AuditSeverity;
  title: string;
  description: string;
  scenario?: string;
  expected: string;
  actual: string;
  recommendation: string;
  codeLocation?: string;
}

export type AuditCategory =
  | 'primitive_ranges'
  | 'trigger_gates'
  | 'guidance_quality'
  | 'state_transitions'
  | 'positive_intelligence'
  | 'guardrail_enforcement'
  | 'edge_cases';

export interface AuditScenario {
  id: string;
  name: string;
  description: string;
  messages: Array<{
    text: string;
    expectedRegime?: Regime;
    expectedBenefitState?: BenefitState;
    expectedTriggerDeep?: boolean;
    expectedChargeRange?: [number, number];
    expectedThreatRange?: [number, number];
  }>;
}

export interface AuditReport {
  id: string;
  timestamp: number;
  duration: number;
  scenariosRun: number;
  findings: AuditFinding[];
  summary: AuditSummary;
  claudeAssessment: string;
  status: 'pass' | 'warning' | 'fail';
}

export interface AuditSummary {
  totalFindings: number;
  critical: number;
  warning: number;
  info: number;
  pass: number;
  categoryCounts: Record<AuditCategory, number>;
  overallScore: number; // 0-100
}

// ============================================================================
// SYNTHETIC SCENARIOS
// ============================================================================

const AUDIT_SCENARIOS: AuditScenario[] = [
  // ---- Scenario 1: Happy path — friendly customer inquiry ----
  {
    id: 'happy-path-inquiry',
    name: 'Happy Path Customer Inquiry',
    description: 'A friendly customer asks about product features. Should stay in connection regime with low threat.',
    messages: [
      {
        text: 'Hi! I heard about your product and I\'m curious how it works.',
        expectedRegime: 'connection',
        expectedTriggerDeep: false,
        expectedChargeRange: [0, 1],
        expectedThreatRange: [0, 0.3],
      },
      {
        text: 'That sounds great! Can you tell me more about the pricing?',
        expectedRegime: 'connection',
        expectedBenefitState: 'exploring',
        expectedTriggerDeep: false,
        expectedChargeRange: [0.1, 1],
        expectedThreatRange: [0, 0.25],
      },
      {
        text: 'The enterprise plan looks perfect for our team. What are the next steps?',
        expectedBenefitState: 'ready_to_close',
        expectedTriggerDeep: false,
        expectedChargeRange: [0.2, 1],
        expectedThreatRange: [0, 0.2],
      },
    ],
  },

  // ---- Scenario 2: Escalation — angry customer ----
  {
    id: 'escalation-angry',
    name: 'Escalation — Angry Customer',
    description: 'Customer becomes increasingly angry about a billing issue. Should detect escalation and raise threat.',
    messages: [
      {
        text: 'I noticed I was charged twice on my last invoice. Can you look into this?',
        expectedRegime: 'connection',
        expectedThreatRange: [0, 0.4],
      },
      {
        text: 'This is the third time this has happened. I\'m really frustrated with your billing system.',
        expectedThreatRange: [0.2, 0.8],
      },
      {
        text: 'I want a full refund immediately or I\'m filing a chargeback. This is unacceptable.',
        expectedThreatRange: [0.4, 1],
        expectedChargeRange: [-1, -0.1],
      },
    ],
  },

  // ---- Scenario 3: Repair attempt after conflict ----
  {
    id: 'repair-after-conflict',
    name: 'Repair After Conflict',
    description: 'Customer was angry but begins to de-escalate. Repair intent should block deep triggers.',
    messages: [
      {
        text: 'Your product completely broke our workflow and we lost data.',
        expectedThreatRange: [0.3, 1],
        expectedChargeRange: [-1, -0.1],
      },
      {
        text: 'I appreciate you looking into this. I was frustrated but I understand these things happen.',
        expectedTriggerDeep: false,
        expectedChargeRange: [-0.3, 0.5],
      },
      {
        text: 'Thank you for the quick resolution. Let\'s work together to prevent this in the future.',
        expectedRegime: 'repair',
        expectedTriggerDeep: false,
        expectedChargeRange: [0, 1],
      },
    ],
  },

  // ---- Scenario 4: Informational FAQ persistence ----
  {
    id: 'informational-faq',
    name: 'Informational FAQ Persistence',
    description: 'Customer asks multiple FAQ-style questions. Should NOT trigger fixation despite topic persistence.',
    messages: [
      {
        text: 'What is your refund policy?',
        expectedTriggerDeep: false,
        expectedThreatRange: [0, 0.3],
      },
      {
        text: 'How do I cancel my subscription?',
        expectedTriggerDeep: false,
        expectedThreatRange: [0, 0.3],
      },
      {
        text: 'What happens to my data after cancellation?',
        expectedTriggerDeep: false,
        expectedThreatRange: [0, 0.3],
      },
      {
        text: 'Can I get a prorated refund for the remaining billing period?',
        expectedTriggerDeep: false,
        expectedThreatRange: [0, 0.4],
      },
    ],
  },

  // ---- Scenario 5: Trust building journey ----
  {
    id: 'trust-building',
    name: 'Trust Building Journey',
    description: 'Customer gradually builds trust over multiple turns. Trust gain should be cumulative.',
    messages: [
      {
        text: 'I\'m evaluating several options. What makes your product different?',
        expectedBenefitState: 'exploring',
      },
      {
        text: 'I appreciate your honest comparison. Most vendors just trash the competition.',
        expectedChargeRange: [0, 1],
      },
      {
        text: 'That\'s exactly what our team needs. I feel confident this would solve our problem.',
      },
      {
        text: 'Let\'s set up a pilot. Our team of 50 could start next month.',
        expectedBenefitState: 'ready_to_close',
      },
    ],
  },

  // ---- Scenario 6: Withdrawal pattern ----
  {
    id: 'withdrawal-pattern',
    name: 'Withdrawal Pattern',
    description: 'Customer gradually disengages. Distance should increase, charge should decrease.',
    messages: [
      {
        text: 'We\'ve been using your product for a while now.',
        expectedRegime: 'connection',
      },
      {
        text: 'Hmm, I\'m not sure it\'s really working for us anymore.',
        expectedChargeRange: [-0.5, 0.2],
      },
      {
        text: 'Yeah, we\'ll think about it. Maybe.',
      },
    ],
  },

  // ---- Scenario 7: Charge flip — positive to negative ----
  {
    id: 'charge-flip',
    name: 'Charge Flip — Positive to Negative',
    description: 'Customer starts positive but flips to negative after a bad experience. Should detect charge flip.',
    messages: [
      {
        text: 'I love your product! It\'s been amazing for our team.',
        expectedChargeRange: [0.3, 1],
        expectedThreatRange: [0, 0.2],
      },
      {
        text: 'Wait, what? You\'re raising prices by 300%? After we just renewed?',
        expectedChargeRange: [-1, -0.2],
        expectedThreatRange: [0.3, 1],
      },
      {
        text: 'This feels like a bait and switch. I trusted you.',
        expectedChargeRange: [-1, -0.3],
        expectedThreatRange: [0.4, 1],
      },
    ],
  },

  // ---- Scenario 8: Edge case — empty/minimal messages ----
  {
    id: 'edge-minimal',
    name: 'Edge Case — Minimal Messages',
    description: 'Very short or ambiguous messages. Engine should handle gracefully without crashing or extreme values.',
    messages: [
      { text: 'ok' },
      { text: '...' },
      { text: 'hmm' },
      { text: '?' },
    ],
  },

  // ---- Scenario 9: Mixed signals — commitment with objection ----
  {
    id: 'mixed-signals',
    name: 'Mixed Signals — Commitment with Objection',
    description: 'Customer shows interest but raises objections simultaneously. Engine should not over-index on either signal.',
    messages: [
      {
        text: 'I\'m interested in the enterprise plan but the price seems too high for what we get.',
      },
      {
        text: 'I want to sign up but I need to convince my CFO first. Can you help me build a business case?',
      },
    ],
  },

  // ---- Scenario 10: Rapid regime cycling ----
  {
    id: 'rapid-cycling',
    name: 'Rapid Regime Cycling',
    description: 'Customer oscillates between positive and negative rapidly. Engine should detect orbit/fixation patterns.',
    messages: [
      {
        text: 'Your product is great when it works.',
        expectedChargeRange: [0, 0.8],
      },
      {
        text: 'But it crashed again today and we lost an hour of work.',
        expectedChargeRange: [-0.8, 0],
      },
      {
        text: 'The support team was really helpful though, got us back up quickly.',
        expectedChargeRange: [0, 0.8],
      },
      {
        text: 'And then it crashed AGAIN. This is a pattern.',
        expectedChargeRange: [-0.8, 0],
      },
    ],
  },
];

// ============================================================================
// AUDIT ENGINE
// ============================================================================

let auditReports: AuditReport[] = [];

/**
 * Run a single scenario through the runtime and collect findings
 */
async function auditScenario(scenario: AuditScenario): Promise<AuditFinding[]> {
  const findings: AuditFinding[] = [];
  const conversationId = `audit-${scenario.id}-${Date.now()}`;
  let previousState = createInitialState(conversationId);
  let turnIndex = 0;

  for (const msg of scenario.messages) {
    turnIndex++;
    const findingPrefix = `${scenario.id}-t${turnIndex}`;

    try {
      // Run the message through the runtime
      const result = await processMessage(conversationId, msg.text, false);
      const state = result.state;

      // ---- Check 1: Primitive range validation ----
      const primitiveChecks: Array<{ name: string; value: number; min: number; max: number }> = [
        { name: 'mass', value: state.mass, min: 0, max: 1 },
        { name: 'distance', value: state.distance, min: 0, max: 1 },
        { name: 'charge', value: state.charge, min: -1, max: 1 },
        { name: 'threat', value: state.threat, min: 0, max: 1 },
        { name: 'momentum', value: state.momentum, min: 0, max: 1 },
        { name: 'acceleration', value: state.acceleration, min: 0, max: 1 },
        { name: 'fixation', value: state.fixation, min: 0, max: 1 },
        { name: 'orbit', value: state.orbit, min: 0, max: 1 },
        { name: 'confidence', value: state.confidence, min: 0, max: 1 },
        { name: 'rapportGain', value: state.rapportGain, min: 0, max: 1 },
        { name: 'trustGain', value: state.trustGain, min: 0, max: 1 },
      ];

      for (const check of primitiveChecks) {
        if (check.value < check.min || check.value > check.max) {
          findings.push({
            id: `${findingPrefix}-range-${check.name}`,
            category: 'primitive_ranges',
            severity: 'critical',
            title: `${check.name} out of range`,
            description: `Primitive "${check.name}" returned ${check.value}, outside expected range [${check.min}, ${check.max}].`,
            scenario: scenario.name,
            expected: `[${check.min}, ${check.max}]`,
            actual: `${check.value}`,
            recommendation: `Clamp ${check.name} in updateState() or analyzeFast() to enforce range bounds.`,
            codeLocation: 'server/nervous-system/dynamics/runtime.ts:updateState()',
          });
        }
      }

      // ---- Check 2: Expected regime ----
      if (msg.expectedRegime && state.regime !== msg.expectedRegime) {
        findings.push({
          id: `${findingPrefix}-regime`,
          category: 'state_transitions',
          severity: 'warning',
          title: `Unexpected regime: ${state.regime}`,
          description: `Expected regime "${msg.expectedRegime}" but got "${state.regime}" for message: "${msg.text.substring(0, 80)}..."`,
          scenario: scenario.name,
          expected: msg.expectedRegime,
          actual: state.regime,
          recommendation: `Review analyzeFast() prompt or regime classification logic.`,
          codeLocation: 'server/nervous-system/dynamics/runtime.ts:analyzeFast()',
        });
      }

      // ---- Check 3: Expected benefit state ----
      if (msg.expectedBenefitState && state.benefitState !== msg.expectedBenefitState) {
        findings.push({
          id: `${findingPrefix}-benefit`,
          category: 'positive_intelligence',
          severity: 'warning',
          title: `Unexpected benefit state: ${state.benefitState}`,
          description: `Expected benefit state "${msg.expectedBenefitState}" but got "${state.benefitState}" for message: "${msg.text.substring(0, 80)}..."`,
          scenario: scenario.name,
          expected: msg.expectedBenefitState,
          actual: state.benefitState,
          recommendation: `Review benefit state determination logic in processMessage().`,
          codeLocation: 'server/nervous-system/dynamics/runtime.ts:processMessage()',
        });
      }

      // ---- Check 4: Expected trigger behavior ----
      if (msg.expectedTriggerDeep !== undefined && result.deepTriggered !== msg.expectedTriggerDeep) {
        findings.push({
          id: `${findingPrefix}-trigger`,
          category: 'trigger_gates',
          severity: msg.expectedTriggerDeep ? 'warning' : 'critical',
          title: `Unexpected deep trigger: ${result.deepTriggered ? 'FIRED' : 'NOT FIRED'}`,
          description: `Expected deep trigger to be ${msg.expectedTriggerDeep} but got ${result.deepTriggered}. Reasons: ${result.triggerReasons.join(', ') || 'none'}`,
          scenario: scenario.name,
          expected: `deepTriggered=${msg.expectedTriggerDeep}`,
          actual: `deepTriggered=${result.deepTriggered}, reasons=[${result.triggerReasons.join(', ')}]`,
          recommendation: msg.expectedTriggerDeep
            ? 'Trigger thresholds may be too high — review DEFAULT_TRIGGERS.'
            : 'Trigger is over-firing — review checkDeepTriggers() gate logic.',
          codeLocation: 'server/nervous-system/dynamics/runtime.ts:checkDeepTriggers()',
        });
      }

      // ---- Check 5: Expected charge range ----
      if (msg.expectedChargeRange) {
        const [minCharge, maxCharge] = msg.expectedChargeRange;
        if (state.charge < minCharge || state.charge > maxCharge) {
          findings.push({
            id: `${findingPrefix}-charge-range`,
            category: 'primitive_ranges',
            severity: 'warning',
            title: `Charge outside expected range`,
            description: `Expected charge in [${minCharge}, ${maxCharge}] but got ${state.charge.toFixed(3)} for: "${msg.text.substring(0, 80)}..."`,
            scenario: scenario.name,
            expected: `[${minCharge}, ${maxCharge}]`,
            actual: `${state.charge.toFixed(3)}`,
            recommendation: `Review analyzeFast() prompt for charge calibration.`,
            codeLocation: 'server/nervous-system/dynamics/runtime.ts:analyzeFast()',
          });
        }
      }

      // ---- Check 6: Expected threat range ----
      if (msg.expectedThreatRange) {
        const [minThreat, maxThreat] = msg.expectedThreatRange;
        if (state.threat < minThreat || state.threat > maxThreat) {
          findings.push({
            id: `${findingPrefix}-threat-range`,
            category: 'primitive_ranges',
            severity: 'warning',
            title: `Threat outside expected range`,
            description: `Expected threat in [${minThreat}, ${maxThreat}] but got ${state.threat.toFixed(3)} for: "${msg.text.substring(0, 80)}..."`,
            scenario: scenario.name,
            expected: `[${minThreat}, ${maxThreat}]`,
            actual: `${state.threat.toFixed(3)}`,
            recommendation: `Review analyzeFast() prompt for threat calibration.`,
            codeLocation: 'server/nervous-system/dynamics/runtime.ts:analyzeFast()',
          });
        }
      }

      // ---- Check 7: Guidance guardrail enforcement ----
      if (state.regime === 'rupture' || state.regime === 'escalation') {
        if (result.guidance.priority === 'low') {
          findings.push({
            id: `${findingPrefix}-guardrail-priority`,
            category: 'guardrail_enforcement',
            severity: 'critical',
            title: `Low priority in ${state.regime} regime`,
            description: `Guidance priority is "low" while in "${state.regime}" regime. This should be at least "high".`,
            scenario: scenario.name,
            expected: 'high or critical',
            actual: result.guidance.priority,
            recommendation: `Review applyGuardrails() in lexicon.ts for priority enforcement.`,
            codeLocation: 'server/nervous-system/dynamics/lexicon.ts:applyGuardrails()',
          });
        }
      }

      // ---- Check 8: Coherence — threat vs charge alignment ----
      if (state.threat > 0.7 && state.charge > 0.5) {
        findings.push({
          id: `${findingPrefix}-coherence-threat-charge`,
          category: 'primitive_ranges',
          severity: 'warning',
          title: `Incoherent: high threat (${state.threat.toFixed(2)}) with high positive charge (${state.charge.toFixed(2)})`,
          description: `High threat and high positive charge simultaneously is unusual. This may indicate the LLM is not calibrating threat/charge coherently.`,
          scenario: scenario.name,
          expected: 'High threat should correlate with negative or neutral charge',
          actual: `threat=${state.threat.toFixed(2)}, charge=${state.charge.toFixed(2)}`,
          recommendation: `Add coherence constraints to analyzeFast() prompt or post-process results.`,
          codeLocation: 'server/nervous-system/dynamics/runtime.ts:analyzeFast()',
        });
      }

      // ---- Check 9: Trust gain monotonicity in positive scenarios ----
      if (state.charge > 0.3 && state.threat < 0.2 && previousState.trustGain > state.trustGain) {
        findings.push({
          id: `${findingPrefix}-trust-regression`,
          category: 'positive_intelligence',
          severity: 'info',
          title: `Trust decreased in positive context`,
          description: `Trust went from ${previousState.trustGain.toFixed(2)} to ${state.trustGain.toFixed(2)} despite positive charge and low threat.`,
          scenario: scenario.name,
          expected: 'Trust should be stable or increasing in positive contexts',
          actual: `trustGain: ${previousState.trustGain.toFixed(2)} → ${state.trustGain.toFixed(2)}`,
          recommendation: `Review trust decay logic — may be too aggressive in positive contexts.`,
          codeLocation: 'server/nervous-system/dynamics/runtime.ts:processMessage()',
        });
      }

      previousState = state;
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      findings.push({
        id: `${findingPrefix}-error`,
        category: 'edge_cases',
        severity: 'critical',
        title: `Runtime error on message`,
        description: `processMessage() threw: ${message}`,
        scenario: scenario.name,
        expected: 'No errors',
        actual: message,
        recommendation: `Add error handling for this scenario.`,
        codeLocation: 'server/nervous-system/dynamics/runtime.ts:processMessage()',
      });
    }
  }

  return findings;
}

/**
 * Ask Claude to provide a holistic assessment of the audit findings
 */
async function getClaudeAssessment(
  findings: AuditFinding[],
  scenariosRun: number
): Promise<string> {
  const criticalFindings = findings.filter(f => f.severity === 'critical');
  const warningFindings = findings.filter(f => f.severity === 'warning');
  const infoFindings = findings.filter(f => f.severity === 'info');

  const findingsSummary = findings.map(f =>
    `[${f.severity.toUpperCase()}] ${f.category}: ${f.title}\n  ${f.description}\n  Expected: ${f.expected}\n  Actual: ${f.actual}`
  ).join('\n\n');

  try {
    const response = await governedClaude.messages.create({
      model: MODELS.generation,
      max_tokens: 2048,
      messages: [{
        role: 'user',
        content: `You are auditing an emotional intelligence engine that analyzes customer conversations in real-time. The engine computes emotional primitives (mass, distance, charge, threat), detects regime states (connection, escalation, rupture, repair, etc.), and generates guidance for customer-facing agents.

A behavioral correctness audit ran ${scenariosRun} scenarios and found:
- ${criticalFindings.length} critical findings
- ${warningFindings.length} warnings
- ${infoFindings.length} informational notes

FINDINGS:
${findingsSummary || 'No findings — all scenarios passed.'}

Provide a concise assessment (3-5 paragraphs):
1. Overall behavioral correctness rating (A-F grade)
2. Most concerning patterns across findings
3. Root cause analysis for recurring issues
4. Priority remediation recommendations
5. Confidence level in the engine's production readiness

Be specific and actionable. Reference specific findings by category.`
      }]
    });

    return response.content[0].type === 'text' ? response.content[0].text : 'Assessment unavailable';
  } catch (error: unknown) {
    generalLog.error('[BehavioralAudit] Claude assessment failed:', error);
    return `Assessment unavailable: ${error instanceof Error ? error.message : String(error)}`;
  }
}

/**
 * Run the full behavioral correctness audit
 */
export async function runBehavioralAudit(
  scenarioIds?: string[]
): Promise<AuditReport> {
  const startTime = Date.now();
  const allFindings: AuditFinding[] = [];

  // Select scenarios
  const scenarios = scenarioIds
    ? AUDIT_SCENARIOS.filter(s => scenarioIds.includes(s.id))
    : AUDIT_SCENARIOS;

  generalLog.info(`[BehavioralAudit] Starting audit with ${scenarios.length} scenarios`);

  // Run each scenario
  for (const scenario of scenarios) {
    generalLog.info(`[BehavioralAudit] Running scenario: ${scenario.name}`);
    try {
      const findings = await auditScenario(scenario);
      allFindings.push(...findings);
    } catch (error: unknown) {
      allFindings.push({
        id: `${scenario.id}-fatal`,
        category: 'edge_cases',
        severity: 'critical',
        title: `Scenario "${scenario.name}" failed to complete`,
        description: error.message,
        scenario: scenario.name,
        expected: 'Scenario completes without fatal errors',
        actual: `Fatal error: ${error.message}`,
        recommendation: 'Investigate runtime stability for this scenario type.',
      });
    }
  }

  // Get Claude's holistic assessment
  const claudeAssessment = await getClaudeAssessment(allFindings, scenarios.length);

  // Build summary
  const critical = allFindings.filter(f => f.severity === 'critical').length;
  const warning = allFindings.filter(f => f.severity === 'warning').length;
  const info = allFindings.filter(f => f.severity === 'info').length;
  const pass = allFindings.filter(f => f.severity === 'pass').length;

  const categoryCounts: Record<AuditCategory, number> = {
    primitive_ranges: 0,
    trigger_gates: 0,
    guidance_quality: 0,
    state_transitions: 0,
    positive_intelligence: 0,
    guardrail_enforcement: 0,
    edge_cases: 0,
  };
  for (const f of allFindings) {
    categoryCounts[f.category]++;
  }

  // Score: 100 - (critical * 15) - (warning * 5) - (info * 1), min 0
  const overallScore = Math.max(0, 100 - (critical * 15) - (warning * 5) - (info * 1));

  const report: AuditReport = {
    id: `audit-${Date.now()}`,
    timestamp: Date.now(),
    duration: Date.now() - startTime,
    scenariosRun: scenarios.length,
    findings: allFindings,
    summary: {
      totalFindings: allFindings.length,
      critical,
      warning,
      info,
      pass,
      categoryCounts,
      overallScore,
    },
    claudeAssessment,
    status: critical > 0 ? 'fail' : warning > 3 ? 'warning' : 'pass',
  };

  // Store report
  auditReports.unshift(report);
  if (auditReports.length > 20) {
    auditReports = auditReports.slice(0, 20);
  }

  generalLog.info(`[BehavioralAudit] Audit complete: score=${overallScore}, findings=${allFindings.length} (${critical}C/${warning}W/${info}I)`);

  return report;
}

/**
 * Run a quick audit (subset of scenarios for faster feedback)
 */
